<template><section class="form-page container"><div class="eyebrow">Konten baru</div><h1>Tulis berita</h1><BeritaForm :kategori="kategori.list" @submit="submit" /></section></template><script setup>definePageMeta({middleware:'admin'});const kategori=useKategoriStore();const store=useBeritaStore();await kategori.fetchAll();async function submit(data){await store.create(data);navigateTo('/admin/berita')}</script>
